mapper.delete:
delete from t_cruise_task
where
    task_id = #{TaskId, jdbcType=VARCHAR}

mapper.update:
update t_cruise_task a


        and task_id = #{TaskId, jdbcType=VARCHAR}


        and plan_id = #{PlanId, jdbcType=BIGINT}


        and area_id = #{AreaId, jdbcType=VARCHAR}


        and name = #{Name, jdbcType=VARCHAR}


        and type = #{Type, jdbcType=INTEGER}


        and if_run = #{IfRun, jdbcType=INTEGER}


        and robot_id = #{RobotId, jdbcType=BIGINT}


        and date_type = #{Datetype, jdbcType=INTEGER}


        and remark1 = #{Remark1, jdbcType=INTEGER}


        and task_type = #{TaskType, jdbcType=INTEGER}


        and start_time = #{StartTime, jdbcType=TIMESTAMP}


        and create_time = #{CreateTime, jdbcType=TIMESTAMP}


where and task_id = #{TaskId, jdbcType=VARCHAR}

mapper.select:
select
task_id,
plan_id,
area_id,
name,
type,
if_run,
robot_id,
date_type,
remark1,
task_type,
start_time,
create_time
from t_cruise_task
where 1 = 1

    and task_id = #{TaskId, jdbcType=VARCHAR}


    and plan_id = #{PlanId, jdbcType=BIGINT}


    and area_id = #{AreaId, jdbcType=VARCHAR}


    and name = #{Name, jdbcType=VARCHAR}


    and type = #{Type, jdbcType=INTEGER}


    and if_run = #{IfRun, jdbcType=INTEGER}


    and robot_id = #{RobotId, jdbcType=BIGINT}


    and date_type = #{Datetype, jdbcType=INTEGER}


    and remark1 = #{Remark1, jdbcType=INTEGER}


    and task_type = #{TaskType, jdbcType=INTEGER}


    and start_time = #{StartTime, jdbcType=TIMESTAMP}


